/* Reveal-Animation (gesteuert von <Reveal/>). Ohne JS bleibt alles sichtbar. */
.ov-reveal {
  /* 2.0: nur transform/opacity (kein filter: blur – teuer beim Scrollen) */
  transition:
    opacity 700ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 700ms cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--ov-delay, 0ms);
}
.js-ready .ov-reveal:not(.is-visible) {
  opacity: 0;
  transform: translate3d(0, 24px, 0);
}
.js-ready .ov-reveal[data-dir="left"]:not(.is-visible) { transform: translate3d(-32px, 0, 0); }
.js-ready .ov-reveal[data-dir="right"]:not(.is-visible) { transform: translate3d(32px, 0, 0); }
.js-ready .ov-reveal[data-dir="scale"]:not(.is-visible) { transform: scale(0.96); }
@media (prefers-reduced-motion: reduce) {
  .js-ready .ov-reveal:not(.is-visible) { opacity: 1; transform: none; }
}

